using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class PointerSpanChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify()=>VerifyWithCapture(null);
 public static void VerifyWithCapture(Action<ConstructionSite,ConstructionBlock> capture){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(QuestSlice).GetField("state",flags);var original=field.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused;var held=(CarryItem[])typeof(QuestSlice).GetField("held",flags).GetValue(slice);var previousHeld=(CarryItem[])held.Clone();var visitor=slice.GetComponentsInChildren<VillagerExploration>()[0];var visitorAt=visitor.transform.position;var visitorRotation=visitor.transform.rotation;
  god.Interrupt("Pointer spans QA");foreach(var person in slice.GetComponentsInChildren<VillagerExploration>()){person.ResetTask();person.GetComponent<VillagerSocial>().ResetTask();person.GetComponent<VillagerResourceGathering>().Cancel();person.GetComponent<VillagerBlockPlay>().ResetTask();}var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};test.Hybrid.time=200;field.SetValue(slice,test);slice.GetComponentInChildren<VillageFamilies>().ResetWorld();for(int i=0;i<held.Length;i++)held[i]=null;var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);
  Ray Aim(float x=1.1f)=>new Ray(site.World(new Vector3(x,12,-12)),Vector3.down);
  ConstructionBlock Put(float x){var b=site.blocks.First(b=>b.Shape==ConstructionShape.Column&&!b.Attached);Require(site.Drop(b,site.World(new Vector3(x,2.4f,-12)),site.transform.rotation),"Could not stage support");return b;}
  bool Grab(ConstructionBlock b)=>(bool)typeof(QuestSlice).GetMethod("TryGrab",flags).Invoke(slice,new object[]{1,b.Item});
  void Release(Ray ray)=>typeof(QuestSlice).GetMethod("Release",flags).Invoke(slice,new object[]{1,ray});
  try{
   site.Paused=false;site.ResetConstruction();site.Recipe=BuildRecipe.Tower;var left=Put(-2);Put(2);var roof=site.blocks.First(b=>b.Shape==ConstructionShape.Slab);Physics.SyncTransforms();
   Require(Grab(roof),"Native slab pickup refused");string before=JsonUtility.ToJson(test);int snaps=site.successfulSnaps;Require(site.PlacementPoint(roof,Aim(),out var point)&&Vector3.Distance(site.Local(point),new Vector3(0,5.4f,-12))<.01f,"Pointer did not select the gap-spanning roof");site.PreviewRay(roof,Aim());var preview=(LineRenderer)typeof(ConstructionSite).GetField("preview",flags).GetValue(site);Require(preview.enabled&&test.placeContributions==null&&before==JsonUtility.ToJson(test)&&site.successfulSnaps==snaps&&!roof.Attached,"Preview changed geometry/history or failed to show supported span");capture?.Invoke(site,roof);
   Release(Aim());Require(held[1]==null&&roof.Attached&&Vector3.Distance(roof.Body.position,new Vector3(0,5.4f,-12))<.01f,"Native pointer release disagreed with preview");Require(site.TryShelterSpot(.4f*QuestSlice.VillagerScale+.08f,1.661f*QuestSlice.VillagerScale,out _,out _)&&!site.RecipeComplete,"Player roof did not create actual recipe-independent cover");Require(test.placeContributions?.records.Length==1&&test.placeContributions.records[0].actor=="player","Native span not recorded once as player placement");
   var walker=visitor.GetComponent<IslandNavigator>();test.Social(0).restNeed=.95f;Require(site.TryShelterSpot(walker.profile.radius+.08f,walker.profile.height,out _,out var entry),"Player canopy entry missing");visitor.transform.position=entry;walker.ResetRoute();Require(visitor.TryShelter(site),"Villager refused player-pointer shelter");for(int i=0;i<3000&&test.Social(0).shelterRests==0;i++){test.Hybrid.time+=.05f;visitor.Tick(.05f,false);}Require(test.Social(0).shelterRests==1&&test.Social(0).Place(0)?.visits==1,"Player-pointer roof did not produce native shelter use");visitor.ResetTask();
   site.ReturnLoose(roof);var beam=site.blocks.First(b=>b.Shape==ConstructionShape.Beam);Require(Grab(beam),"Native beam pickup refused");Physics.SyncTransforms();Require(site.PlacementPoint(beam,Aim(),out point)&&Vector3.Distance(site.Local(point),new Vector3(0,5.4f,-12))<.01f,"Beam pointer span not selected");Release(Aim());Require(beam.Attached&&test.placeContributions.records.Length==2,"Native beam release failed or duplicated credit");site.ReturnLoose(beam);
   Physics.SyncTransforms();Require(site.PlacementPoint(roof,Aim(2),out point)&&Mathf.Abs(site.Local(point).x-2)<.01f,"Aiming at the support centre lost ordinary stacking");
   left.Item.held=true;Require(!site.FindSnap(roof,PointerPoint(roof,Aim()),site.transform.rotation,out _,out _,out _),"Held opposite support supplied a span");left.Item.held=false;
   var obstacle=site.blocks.First(b=>b.Shape==ConstructionShape.Cube&&!b.Attached);var old=obstacle.Body.position;obstacle.Body.position=new Vector3(0,5.4f,-12);Require(!site.FindSnap(roof,PointerPoint(roof,Aim()),site.transform.rotation,out _,out _,out _),"Occupied roof space accepted span");obstacle.Body.position=old;
   site.ReturnLoose(left);Physics.SyncTransforms();Require(Grab(roof),"Second native pickup refused");Release(Aim());Require(!roof.Attached&&test.placeContributions.records.Length==2,"One-sided failed drop snapped or fabricated contribution");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid(),"Span contribution save invalid");Debug.Log("BWVR_POINTER_SPAN_PASS: native pickup/raycast preview/release, real braced cover, preview purity, player attribution once, ordinary stacking, held/missing support and occupied-space gates");
  }finally{for(int i=0;i<held.Length;i++)held[i]=previousHeld[i];foreach(var b in site.blocks)b.Item.held=false;site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;field.SetValue(slice,original);visitor.transform.SetPositionAndRotation(visitorAt,visitorRotation);visitor.GetComponent<IslandNavigator>().ResetRoute();}
  Vector3 PointerPoint(ConstructionBlock b,Ray ray){Require(site.PlacementPoint(b,ray,out var point),"No surface contact for negative probe");return point;}
 }
}
}
